<?php $user = require_login(); $stmt = $pdo->prepare('SELECT cr.status, cr.created_at, cr.refund_amount, b.booking_code, e.name AS equipment_name FROM cancellation_requests cr JOIN bookings b ON b.id = cr.booking_id JOIN equipment e ON e.id = b.equipment_id WHERE cr.user_id = ? ORDER BY cr.created_at DESC LIMIT 5'); $stmt->execute([$user['id']]); $cancellationHistory = $stmt->fetchAll(); ?>
<section class="dashboard-shell"><div class="container"><div class="dashboard-heading"><div><span class="eyebrow">Account settings</span><h1>Profil saya.</h1><p>Perbarui informasi kontak untuk kebutuhan reservasi.</p></div></div><div class="dashboard-layout"><?php require __DIR__ . '/../layout/dashboard_sidebar.php'; ?><div class="dashboard-main"><div class="form-card"><h2 style="font-size:20px">Informasi pribadi</h2><p class="small">Data ini digunakan sebagai kontak utama pada reservasi.</p><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="update_profile"><div class="form-grid"><div class="form-group"><label for="name">Nama lengkap</label><input class="form-control" id="name" name="name" value="<?= e($user['name']) ?>" required></div><div class="form-group"><label for="email">Email</label><input class="form-control" type="email" id="email" name="email" value="<?= e($user['email']) ?>" required></div><div class="form-group"><label for="phone">Nomor telepon</label><input class="form-control" id="phone" name="phone" value="<?= e($user['phone'] ?? '') ?>"></div><div class="form-group"><label>Peran akun</label><input class="form-control" value="<?= e(ucfirst($user['role'])) ?>" disabled></div></div><button class="btn btn-primary" type="submit">Simpan perubahan ↗</button></form></div><div class="panel-card" style="margin-top:20px"><div class="panel-head"><h2>Status permintaan pembatalan</h2><a class="text-link" href="<?= e(url('my-bookings')) ?>">Riwayat booking ↗</a></div><?php if (!$cancellationHistory): ?><p class="small">Belum ada permintaan pembatalan.</p><?php else: ?><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Kode booking</th><th>Perlengkapan</th><th>Status</th><th>Refund tercatat</th></tr></thead><tbody><?php foreach ($cancellationHistory as $request): ?><tr><td><strong><?= e($request['booking_code']) ?></strong></td><td><?= e($request['equipment_name']) ?></td><td><span class="status status-<?= e(status_class($request['status'])) ?>"><?= e(status_text($request['status'])) ?></span></td><td><?= money($request['refund_amount']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div></div></div></section>
